-- Listage de la structure de table db_cabinet_v2. appointments
CREATE TABLE IF NOT EXISTS `appointments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` bigint(20) unsigned NOT NULL,
  `doctor_id` bigint(20) unsigned NOT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `scheduled_at` datetime NOT NULL,
  `duration_minutes` int(11) NOT NULL DEFAULT 30,
  `consultation_type` enum('general','specialized','followup','emergency','control','teleconsultation') NOT NULL DEFAULT 'general',
  `status` enum('planned','confirmed','waiting','in_progress','completed','cancelled','no_show') NOT NULL DEFAULT 'planned',
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `color` varchar(7) DEFAULT '#01a9ac' COMMENT 'Couleur pour FullCalendar',
  `reminder_sent` tinyint(1) NOT NULL DEFAULT 0,
  `arrived_at` datetime DEFAULT NULL COMMENT 'Heure d''arrivée en salle d''attente',
  `started_at` datetime DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointments_created_by_foreign` (`created_by`),
  KEY `appointments_doctor_id_scheduled_at_index` (`doctor_id`,`scheduled_at`),
  KEY `appointments_patient_id_status_index` (`patient_id`,`status`),
  KEY `appointments_scheduled_at_status_index` (`scheduled_at`,`status`),
  CONSTRAINT `appointments_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointments_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `appointments_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

