-- Listage de la structure de table db_cabinet_v2. consultations
CREATE TABLE IF NOT EXISTS `consultations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` bigint(20) unsigned NOT NULL,
  `doctor_id` bigint(20) unsigned NOT NULL,
  `appointment_id` bigint(20) unsigned DEFAULT NULL,
  `consultation_type` enum('general','specialized','followup','emergency','control','teleconsultation') NOT NULL DEFAULT 'general',
  `status` enum('in_progress','completed','archived') NOT NULL DEFAULT 'in_progress',
  `consultation_date` datetime NOT NULL,
  `reason` text DEFAULT NULL COMMENT 'Motif de consultation',
  `symptoms` text DEFAULT NULL,
  `clinical_exam` text DEFAULT NULL COMMENT 'Examen clinique',
  `weight_kg` decimal(5,2) DEFAULT NULL,
  `height_cm` decimal(5,1) DEFAULT NULL,
  `blood_pressure` varchar(20) DEFAULT NULL COMMENT 'Ex: 120/80',
  `heart_rate` int(11) DEFAULT NULL COMMENT 'bpm',
  `temperature` decimal(4,1) DEFAULT NULL COMMENT '°C',
  `spo2` int(11) DEFAULT NULL COMMENT 'Saturation O2 %',
  `diagnosis` text DEFAULT NULL,
  `icd10_code` varchar(20) DEFAULT NULL COMMENT 'Code CIM-10',
  `treatment_plan` text DEFAULT NULL,
  `doctor_notes` text DEFAULT NULL,
  `summary` text DEFAULT NULL COMMENT 'Résumé de consultation',
  `followup_required` tinyint(1) NOT NULL DEFAULT 0,
  `followup_date` date DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `consultations_appointment_id_foreign` (`appointment_id`),
  KEY `consultations_created_by_foreign` (`created_by`),
  KEY `consultations_patient_id_consultation_date_index` (`patient_id`,`consultation_date`),
  KEY `consultations_doctor_id_status_index` (`doctor_id`,`status`),
  CONSTRAINT `consultations_appointment_id_foreign` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consultations_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consultations_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `consultations_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

